:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-order: #0f3460;
  --bg-order-alt: #0a2744;
  --bg-stat: #16213e;
  --bg-stat-accent: #f5a623;
  --bg-footer: #0f0f1a;
  --text-primary: #e8e8f0;
  --text-secondary: #8888aa;
  --text-dark: #1a1a2e;
  --accent-red: #e94560;
  --accent-gold: #f5a623;
  --tag-spirit: #7c4dff;
  --tag-tropical: #00bcd4;
  --tag-gin: #4caf50;
  --tag-sparkling: #ff7043;
  --status-open: #00d4aa;
  --border-subtle: #2a2a4a;
  --radius-card: 14px;
  --radius-item: 8px;
  --radius-tag: 4px;
  --radius-btn: 7px;
}

.bar-tab {
  background: var(--bg-card);
  border-radius: var(--radius-card);
  border: 1px solid var(--border-subtle);
  width: 476px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.tab-header {
  background: var(--bg-header);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
}

.bar-info {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-icon {
  font-size: 22px;
  line-height: 1;
}

.bar-name-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.bar-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.bar-subtitle {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 0;
  line-height: 1;
}

.tab-meta {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tab-status {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  padding: 3px 8px;
  border-radius: 20px;
  background: var(--status-open);
  color: var(--bg-card);
}

.tab-time {
  font-size: 12px;
  color: var(--text-secondary);
}

.orders-grid {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
}

.order-item {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-order);
  border-radius: var(--radius-item);
  padding: 7px 10px;
}

.order-item:nth-child(even) {
  background: var(--bg-order-alt);
}

.drink-emoji {
  font-size: 18px;
  width: 22px;
  text-align: center;
  flex-shrink: 0;
  line-height: 1;
}

.drink-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  flex: 1;
  line-height: 1;
}

.drink-tag {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 6px;
  border-radius: var(--radius-tag);
  color: #fff;
  flex-shrink: 0;
}

.drink-tag.spirit {
  background: var(--tag-spirit);
}

.drink-tag.tropical {
  background: var(--tag-tropical);
}

.drink-tag.gin {
  background: var(--tag-gin);
}

.drink-tag.sparkling {
  background: var(--tag-sparkling);
}

.drink-qty {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 500;
  width: 20px;
  text-align: center;
  flex-shrink: 0;
}

.drink-price {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-gold);
  width: 32px;
  text-align: right;
  flex-shrink: 0;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  padding: 6px 10px;
}

.stat-box {
  background: var(--bg-stat);
  border-radius: var(--radius-item);
  padding: 7px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border: 1px solid var(--border-subtle);
}

.stat-box.accent {
  background: var(--bg-stat-accent);
  border-color: var(--bg-stat-accent);
}

.stat-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}

.stat-box.accent .stat-value {
  color: var(--text-dark);
}

.stat-label {
  font-size: 9px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.stat-box.accent .stat-label {
  color: var(--text-dark);
  opacity: 0.7;
}

.tab-footer {
  background: var(--bg-footer);
  padding: 9px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border-subtle);
}

.bartender-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.bartender-avatar {
  font-size: 20px;
  width: 30px;
  height: 30px;
  background: var(--bg-order);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.bartender-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.bartender-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
}

.bartender-role {
  font-size: 10px;
  color: var(--text-secondary);
  line-height: 1;
}

.footer-actions {
  display: flex;
  gap: 7px;
}

.btn-secondary {
  padding: 6px 12px;
  border-radius: var(--radius-btn);
  font-size: 12px;
  font-weight: 600;
  border: 1px solid var(--border-subtle);
  background: var(--bg-stat);
  color: var(--text-primary);
  cursor: pointer;
}

.btn-primary {
  padding: 6px 14px;
  border-radius: var(--radius-btn);
  font-size: 12px;
  font-weight: 700;
  border: none;
  background: var(--accent-red);
  color: #fff;
  cursor: pointer;
}
